raw:
{
  "spells": [
    {
      "id": "spell_summon_04",
      "theory": "此术先以魔力在器皿边缘织出一圈牵引细线，再将细线系在役灵体表。水与杯壁之间形成一层薄薄的吸附力，役灵才能托住杯底而不使水晃出。契约只维持搬动这一件事，力尽便散，不会让役灵自行取水或倒水。",
      "casting": "左手虚托杯底，右手食指沿杯口顺时针画圆，同时低声念出役灵名，待杯壁出现一圈淡光即可松手。",
      "failure": "淡光未成环，役灵会提前溃散，杯子突然失去托力而歪倒。水泼在桌面上，役灵残影如雾散开，短时间内无法再召同一只。",
      "counters": [
        "在杯底画一道静止符文，可截断牵引细线，使役灵托不住杯子。",
        "用干燥的粗布快速擦过杯壁，破坏魔力附着，役灵会缩回契约空间。"
      ],
      "socialConsequences": "河谷乡约常让见证人看着役灵端水，以确认契约效力。城镇茶馆的侍者欢迎它减少烫伤，但担心客人误以为役灵能无限端送而提出过分要求。琥珀海岸的搬运工则警惕它抢走短途递水的零工，要求雇主在雇用役灵时仍按人头支付码头饮水费。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时杯子常左右摇摆，水会溅出少许。",
        "环线稳定后，役灵能平稳端杯走过平坦地面。",
        "熟练者能控制移动速度，使杯口水面几乎不晃。",
        "更高熟练度下，役灵可绕过小障碍，仍不能离杯自取。"
      ]
    },
    {
      "id": "spell_summon_05",
      "theory": "火蜥投影以魔力在空气中勾出火元素轮廓，再用一条短暂契约线牵住它。投影没有真实血肉，只靠契约线维持形态，因此不能离召唤者太远。它能引燃干燥引火物，却无法控制已燃的大火，契约结束后火星与灰烬一并消散。",
      "casting": "右手拇指与中指相触，在面前画一个不闭合的三角，同时将魔力沿三角边推入空中，待中心出现红点即松指。",
      "failure": "三角未合拢时红点会炸成散乱火星，灼伤近处手指。投影可能只现出半截尾巴便溃散，留下刺鼻焦味，契约线断裂后无法立即重召。",
      "counters": [
        "向投影泼洒细沙可打断契约线，火元素会缩成火星并消散。",
        "用湿泥覆盖三角落点，魔力无法勾出轮廓，投影便不能成形。"
      ],
      "socialConsequences": "城镇铁匠偶尔雇人用投影点燃炭炉，省去反复打火。消防巡丁则要求召唤者远离柴堆与油坊，并在投影消散前守住火种。琥珀海岸的船主担心投影在甲板上引燃缆绳，规定必须由持许可的船员在岸上操作，货主也会要求额外投保。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时投影常缺一角，火星散落范围较大。",
        "轮廓完整后，投影能稳定点燃干燥火绒。",
        "熟练者能控制投影移动，使火焰远离易燃物。",
        "更高熟练度可缩短成形时间，仍受契约时长限制。"
      ]
    },
    {
      "id": "spell_summon_06",
      "theory": "石屑役灵靠魔力在碎石表面形成一层薄壳，壳与地面之间产生短暂吸力，役灵才能托起石屑。契约只规定搬运方向与大致重量，超过限度壳会碎裂。它不能粉碎岩石，也不能把石屑变成武器，载重耗尽后便原地散落。",
      "casting": "双掌覆在碎石堆上，以拇指按压石面画一个方形，然后缓缓抬掌，待石屑随掌浮起半寸即可。",
      "failure": "方形未成形时石屑会突然塌落，砸伤脚背。役灵可能只托起几块碎石便散架，薄壳碎成粉末，同一堆石屑在片刻内无法再次附灵。",
      "counters": [
        "用铁锤敲击承载薄壳的碎石，壳裂后役灵即失去托力。",
        "向石堆浇水使薄壳打滑，吸力无法维持，役灵会自行溃散。"
      ],
      "socialConsequences": "河谷采石场用役灵清理碎石，减少工人扭伤腰背。石匠行会担心雇主借此压低搬运工钱，要求按搬石量而非按役灵数目计酬。琥珀海岸的码头管事允许在指定区域使用，但要求役灵不得进入货舱，以免碎石划破麻袋引发货损纠纷。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时石屑边走边掉，需要频繁停下重附。",
        "薄壳稳定后，役灵能一次搬动一捧碎石。",
        "熟练者能让役灵绕过浅坑，石屑散落明显减少。",
        "更高熟练度可延长托举时间，载重上限不变。"
      ]
    }
  ]
}
